                state.domainState.subjectChoice = d.subjectChoice;
                replyRate = opt.baseRate;
                specificity = opt.specificity;
                words = opt.words;
                if (opt.specificity <= 2) {
                    coachMessage = window.mySimulation.t('coach_subj_generic');
                } else if (opt.specificity === 5) {
                    coachMessage = window.mySimulation.t('coach_subj_strong');
                } else {
                    coachMessage = window.mySimulation.t('coach_subj_decent');
                }
            } else if (period === 2) {
                var op = this.OPENER_OPTIONS[d.openerChoice];
                var re = this.REASON_OPTIONS[d.reasonChoice];
                var as = this.ASK_OPTIONS[d.askChoice];
                var eo = this.EASYOUT_OPTIONS[d.easyOutChoice];
                state.domainState.openerChoice = d.openerChoice;
                state.domainState.reasonChoice = d.reasonChoice;
                state.domainState.askChoice = d.askChoice;
                state.domainState.easyOutChoice = d.easyOutChoice;
                var lift = op.lift + re.lift + as.lift + eo.lift;
                replyRate = Math.max(2, replyRate + lift);
                specificity += op.specificity + re.specificity + as.specificity + eo.specificity;
                words += op.words + re.words + as.words + eo.words;

                var issues = [];
                if (op.specificity <= 1) issues.push(window.mySimulation.t('coach_body_throat'));
                if (re.specificity <= 1) issues.push(window.mySimulation.t('coach_body_substance'));
                if (as.specificity <= 1) issues.push(window.mySimulation.t('coach_body_ask'));
                if (eo.specificity === 0) issues.push(window.mySimulation.t('coach_body_easyout'));
                coachMessage = issues.length === 0
                    ? window.mySimulation.t('coach_body_tight')
                    : issues.join(' ');
            } else if (period === 3) {
                var sgo = this.SIGNOFF_OPTIONS[d.signoffChoice];
                var fup = this.FOLLOWUP_OPTIONS[d.followupChoice];
                state.domainState.signoffChoice = d.signoffChoice;
                state.domainState.followupChoice = d.followupChoice;
                replyRate = Math.max(2, replyRate + sgo.lift + fup.lift);
                specificity += sgo.specificity + fup.specificity;
                words += sgo.words || 0;

                var parts = [];
                if (sgo.specificity <= 1) parts.push(window.mySimulation.t('coach_close_signoff'));
                if (d.followupChoice === 'C') parts.push(window.mySimulation.t('coach_close_too_many'));
                if (d.followupChoice === 'A') parts.push(window.mySimulation.t('coach_close_no_followup'));
                coachMessage = parts.length === 0
                    ? window.mySimulation.t('coach_close_clean')
                    : parts.join(' ');
            }

            replyRate = Math.min(60, Math.max(2, replyRate));
            state.domainState.replyRate = replyRate;
            state.domainState.specificityScore = Math.min(20, specificity);
            state.domainState.wordCount = words;
            state.domainState.coachMessage = coachMessage;
            // Rebuild the series from committed history (state.history holds prior committed rounds),
            // then append the current result. This makes the arrays idempotent under undo — including
            // undo back to the start — so they can never double-count a resubmitted round.
            state.domainState.replyRateHistory = (state.history || []).map(function(h) { return (h.results && typeof h.results.replyRate === 'number') ? h.results.replyRate : 0; });
            state.domainState.specificityHistory = (state.history || []).map(function(h) { return (h.results && typeof h.results.specificity === 'number') ? h.results.specificity : 0; });
            state.domainState.replyRateHistory.push(replyRate);
            state.domainState.specificityHistory.push(state.domainState.specificityScore);

            // platform score maps replyRate through the same 20/35 excellent-good-beginner bands
            // getPerformanceSummary uses for its final verdict, scaled 0 to 100 against the 60 cap
            var platformScore = Math.max(0, Math.min(100, this._scoreFromReplyRate(replyRate)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: platformScore });

            var self = this;
            // The framework advances currentPeriod synchronously once calculateResults returns (and
            // holds it on the final round). Reading the LIVE state on the next tick keeps the briefing,
            // the visible round block, and the preview in sync with the round actually being composed.
            // The previous code added +1 to an already-incremented value, so it skipped the body round.
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
                self._livePreview();
            }, 0);
            setTimeout(function() {
                self._updateCoach(coachMessage);
            }, 400);

            return {
                period: state.currentPeriod,
                replyRate: replyRate,
                specificity: state.domainState.specificityScore,
                wordCount: words,
                coachMessage: coachMessage
            };
        }

        _scoreFromReplyRate(rate) {
            if (rate <= 0) return 0;
            if (rate < 20) return Math.round(40 * rate / 20);
            if (rate < 35) return Math.round(40 + 30 * (rate - 20) / 15);
            if (rate < 60) return Math.round(70 + 30 * (rate - 35) / 25);
            return 100;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('replyRateDisplay', 'domainState.replyRate', (v) => Math.round(v) + '%');
            uiManager.bind('specificityDisplay', 'domainState.specificityScore', (v) => v + '/20');
            uiManager.bind('lengthDisplay', 'domainState.wordCount', (v) => v + ' ' + this._tx('words_unit', 'words'));

            // Live message preview: re-render the email as the player changes any option,
            // instead of only after the round is submitted.
            var self = this;
            ['subjectInput', 'openerInput', 'reasonInput', 'askInput', 'easyOutInput', 'signoffInput', 'followupInput'].forEach(function(id) {
                var el = document.getElementById(id);
                if (!el) return;
                var handler = function() { self._picked[id] = true; try { self._livePreview(); } catch (e) {} };
                el.addEventListener('change', handler);
                el.addEventListener('input', handler);
            });
            // the preview is written from the translation tables, so a language switch rewrites it
            document.addEventListener('express:langchanged', function() { try { self._livePreview(); } catch (e) {} });
            // an undo sends the student back to an earlier round: the framework signals it with period:undone
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function' && !this._undoBound) {
                this._undoBound = true;
                sim.eventBus.on('period:undone', function(st) { try { self._afterUndo(st || sim.state); } catch (e) {} });
            }
        }

        // Show the round the student returns to as on first entry: its briefing and block, the coach note of the
        // last committed round, its fields and those of later rounds unpicked, and the preview drawn from the
        // committed rounds with placeholders for the live one.
        _afterUndo(state) {
            var period = (state && state.currentPeriod) || 1;
            var fields = [['subjectInput'], ['openerInput', 'reasonInput', 'askInput', 'easyOutInput'], ['signoffInput', 'followupInput']];
            for (var r = Math.max(0, period - 1); r < fields.length; r++) {
                for (var i = 0; i < fields[r].length; i++) {
                    var id = fields[r][i];
                    this._picked[id] = false;
                    var el = document.getElementById(id);
                    if (el && el.tagName === 'SELECT') {
                        var blank = -1;
                        for (var k = 0; k < el.options.length; k++) { if (el.options[k].value === '') { blank = k; break; } }
                        el.selectedIndex = blank;
                    }
                }
            }
            this._updateBriefing(state);
            var note = (state && state.domainState) ? state.domainState.coachMessage : '';
            if (note) { this._updateCoach(note); }
            else { var panel = document.getElementById('coachPanel'); if (panel) panel.style.display = 'none'; }
            this._livePreview();
        }

        _tx(key, fallback) {
            var sim = window.mySimulation;
            var s = (sim && typeof sim.t === 'function') ? sim.t(key) : null;
            return (typeof s === 'string' && s && s !== key) ? s : fallback;
        }

        // preview text of an option in the current language, from the pv keys of the tables
        _pv(group, opts, choice) {
            var o = choice ? opts[choice] : null;
            if (!o || !o.text) return '';
            return this._tx('pv_' + group + '_' + String(choice).toLowerCase(), o.text);
        }

        getChartConfig() {
            var self = this;
            var T = function(k, f) { return self._tx(k, f); };
            return {
                replyRateChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: T('chart_reply_label', 'Predicted Reply Rate (%)'),
                            data: [],
                            borderColor: '#0a66c2',
                            backgroundColor: 'rgba(10,102,194,0.12)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.25,
                            pointRadius: 6,
                            pointBackgroundColor: '#0a66c2',
                            pointBorderColor: '#ffffff',
                            pointBorderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: T('chart_reply_title', 'Reply Rate Across Rounds'), color: '#1d2939' },
                            legend: { display: false }
                        },
                        scales: {
                            y: { beginAtZero: true, suggestedMax: 60, title: { display: true, text: T('chart_reply_axis', '% reply') } },
                            x: { title: { display: true, text: T('col_round', 'Round') } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            // Derive the plotted series from committed history so the chart stays correct through undo.
            var series = (state.history || []).map(function(h) { return (h.results && typeof h.results.replyRate === 'number') ? h.results.replyRate : 0; });
            var labels = series.map(function(_, i) { return 'R' + (i + 1); });
            return {
                replyRateChart: {
                    labels: labels,
                    datasets: [{ label: this._tx('chart_reply_label', 'Predicted Reply Rate (%)'), data: series }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var finalRate = (last.results && last.results.replyRate) || 0;
            var finalSpec = (last.results && last.results.specificity) || 0;
            var finalWords = (last.results && last.results.wordCount) || 0;
            var performance, tier;
            var insights = [];
            if (finalRate >= 35) {
                tier = 'excellent';
                performance = window.mySimulation.t('perf_excellent');
                insights.push(window.mySimulation.t('insight_excellent_1'));
                insights.push(window.mySimulation.t('insight_excellent_2'));
            } else if (finalRate >= 20) {
                tier = 'good';
                performance = window.mySimulation.t('perf_good');
                insights.push(window.mySimulation.t('insight_good_1'));
                insights.push(window.mySimulation.t('insight_good_2'));
            } else {
                tier = 'beginner';
                performance = window.mySimulation.t('perf_beginner');
                insights.push(window.mySimulation.t('insight_beginner_1'));
                insights.push(window.mySimulation.t('insight_beginner_2'));
            }
            if (finalWords > 90) insights.push(window.mySimulation.t('insight_too_long'));
            return {
                finalReplyRate: finalRate,
                totalSpecificity: finalSpec,
                wordCount: finalWords,
                performance: performance,
                tier: tier,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.replyRate < 12) return window.mySimulation.t('hint_generic');
            if (results.wordCount > 90) return window.mySimulation.t('hint_too_long');
            if (results.specificity >= 12) return window.mySimulation.t('hint_specific');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'period', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.replyRate', label: 'Reply Rate', i18nKey: 'col_reply_rate', formatter: (v) => Math.round(v) + '%' },
                { key: 'results.specificity', label: 'Specificity', i18nKey: 'col_spec', formatter: (v) => v + '/20' },
                { key: 'results.wordCount', label: 'Words', i18nKey: 'col_words' }
            ];
        }

