        _updateBriefing(state) {
            var period = (state && state.currentPeriod) || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            if (idx < 0) idx = 0;
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl && window.mySimulation && window.mySimulation.t) {
                briefEl.textContent = window.mySimulation.t(round.descKey);
            }

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var blockEl = document.getElementById(this.ROUNDS[i].block);
                if (blockEl) blockEl.style.display = (i === idx) ? 'block' : 'none';
            }
        }

        _updatePreview(state) {
            if (!state || !state.domainState) return;
            var ds = state.domainState;
            var subjEl = document.getElementById('previewSubject');
            var bodyEl = document.getElementById('previewBody');
            var sigEl = document.getElementById('previewSignoff');

            if (subjEl) {
                subjEl.textContent = ds.subjectChoice ? this._pv('subj', this.SUBJECT_OPTIONS, ds.subjectChoice) : '—';
            }

            if (bodyEl) {
                var lines = [];
                if (ds.openerChoice) lines.push(this._pv('open', this.OPENER_OPTIONS, ds.openerChoice));
                if (ds.reasonChoice) {
                    var rTxt = this._pv('reas', this.REASON_OPTIONS, ds.reasonChoice);
                    if (rTxt) lines.push(rTxt);
                }
                if (ds.askChoice) lines.push(this._pv('ask', this.ASK_OPTIONS, ds.askChoice));
                if (ds.easyOutChoice) {
                    var eTxt = this._pv('eo', this.EASYOUT_OPTIONS, ds.easyOutChoice);
                    if (eTxt) lines.push(eTxt);
                }
                bodyEl.textContent = lines.length ? lines.join('\n\n') : '—';
            }

            if (sigEl) {
                sigEl.textContent = ds.signoffChoice ? this._pv('sig', this.SIGNOFF_OPTIONS, ds.signoffChoice) : '';
            }
        }

        _livePreview() {
            var sim = window.mySimulation;
            if (!sim || !sim.state) return;
            var state = sim.state;
            var ds = state.domainState || {};
            var period = state.currentPeriod || 1;
            var picked = this._picked || {};
            // a live field counts only once the student has picked in it
            function sv(id) { var el = document.getElementById(id); return (el && el.value && picked[id]) ? el.value : null; }

            // Progressive draft: live for the round being composed, committed for rounds already submitted.
            var subjectChoice = (period <= 1) ? sv('subjectInput') : ds.subjectChoice;
            var openerChoice, reasonChoice, askChoice, easyOutChoice;
            if (period >= 3) {
                openerChoice = ds.openerChoice; reasonChoice = ds.reasonChoice;
                askChoice = ds.askChoice; easyOutChoice = ds.easyOutChoice;
            } else if (period === 2) {
                openerChoice = sv('openerInput'); reasonChoice = sv('reasonInput');
                askChoice = sv('askInput'); easyOutChoice = sv('easyOutInput');
            }
            var signoffChoice = (period >= 3) ? sv('signoffInput') : ds.signoffChoice;

            var subjEl = document.getElementById('previewSubject');
            var bodyEl = document.getElementById('previewBody');
            var sigEl = document.getElementById('previewSignoff');
            var NL = String.fromCharCode(10) + String.fromCharCode(10);
            if (subjEl) subjEl.textContent = (subjectChoice && this.SUBJECT_OPTIONS[subjectChoice]) ? this._pv('subj', this.SUBJECT_OPTIONS, subjectChoice) : (period <= 1 ? this._tx('pv_subj_none', 'Choose a subject line') : '—');
            if (bodyEl) {
                var lines = [];
                if (openerChoice && this.OPENER_OPTIONS[openerChoice]) lines.push(this._pv('open', this.OPENER_OPTIONS, openerChoice));
                if (reasonChoice && this.REASON_OPTIONS[reasonChoice] && this.REASON_OPTIONS[reasonChoice].text) lines.push(this._pv('reas', this.REASON_OPTIONS, reasonChoice));
                if (askChoice && this.ASK_OPTIONS[askChoice]) lines.push(this._pv('ask', this.ASK_OPTIONS, askChoice));
                if (easyOutChoice && this.EASYOUT_OPTIONS[easyOutChoice] && this.EASYOUT_OPTIONS[easyOutChoice].text) lines.push(this._pv('eo', this.EASYOUT_OPTIONS, easyOutChoice));
                var bodyOpen = period === 2 && !openerChoice && !reasonChoice && !askChoice && !easyOutChoice;
                bodyEl.textContent = lines.length ? lines.join(NL) : (bodyOpen ? this._tx('pv_body_none', 'Choose the four parts of the body') : '—');
            }
            if (sigEl) sigEl.textContent = (signoffChoice && this.SIGNOFF_OPTIONS[signoffChoice]) ? this._pv('sig', this.SIGNOFF_OPTIONS, signoffChoice) : (period >= 3 ? this._tx('pv_sig_none', 'Choose a sign-off') : '');
        }

        _updateCoach(message) {
            var panel = document.getElementById('coachPanel');
            var text = document.getElementById('coachText');
            if (panel && text && message) {
                text.textContent = message;
                panel.style.display = 'block';
            }
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new ColdOutreachAdapter(), {
            simulationType: 'cold_outreach',
            maxPeriods: 3,
            autoSaveInterval: 30000
        });
    });

})();
